import {
  ChevronRight,
  Filter,
  Search,
  SlidersHorizontal,
  X,
} from 'lucide-react';
import {
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import { Link, useSearchParams } from 'react-router-dom';
import { SEO } from '../SEO';
import {
  fetchMarketplaceListings,
  MARKETPLACE_CATEGORY_DEFINITIONS,
} from '../../lib/marketplace';
import { trackMarketplaceEvent } from '../../lib/marketplaceAnalytics';
import type {
  MarketplaceBillingFilter,
  MarketplaceCategoryKey,
  MarketplaceFilters,
  MarketplaceListing,
  MarketplacePriceFilter,
  MarketplaceSort,
} from '../../types/marketplace';
import {
  MarketplaceEmptyState,
  MarketplaceErrorState,
  MarketplaceGridSkeleton,
  MarketplaceListingGrid,
} from './MarketplaceListingGrid';

type MarketplaceBrowsePageProps = {
  title: string;
  description: string;
  canonicalPath: string;
  fixedType?: MarketplaceCategoryKey;
  noIndex?: boolean;
  eyebrow?: string;
};

const validType = (value: string | null): MarketplaceFilters['type'] =>
  value === 'digital-products' ||
  value === 'services' ||
  value === 'courses' ||
  value === 'communities'
    ? value
    : 'all';

const validSort = (value: string | null): MarketplaceSort =>
  value === 'newest' ||
  value === 'price-asc' ||
  value === 'price-desc' ||
  value === 'rating'
    ? value
    : 'relevance';

const validPrice = (value: string | null): MarketplacePriceFilter =>
  value === 'free' || value === 'paid' ? value : 'all';

const validBilling = (value: string | null): MarketplaceBillingFilter =>
  value === 'one-time' || value === 'recurring' ? value : 'all';

const optionalNumber = (value: string | null) => {
  if (!value) return null;
  const number = Number(value);
  return Number.isFinite(number) && number >= 0 ? number : null;
};

const inputClass =
  'h-11 w-full rounded-xl border border-black/10 bg-white px-3 text-sm text-neutral-950 outline-none placeholder:text-neutral-400 focus:border-indigo-500 focus:ring-3 focus:ring-indigo-500/10 dark:border-white/10 dark:bg-white/[0.045] dark:text-white dark:placeholder:text-white/30';

const Filters = ({
  filters,
  categories,
  hasRatings,
  hasBilling,
  hideType,
  onChange,
}: {
  filters: MarketplaceFilters;
  categories: string[];
  hasRatings: boolean;
  hasBilling: boolean;
  hideType: boolean;
  onChange: <Key extends keyof MarketplaceFilters>(
    key: Key,
    value: MarketplaceFilters[Key],
  ) => void;
}) => (
  <div className="space-y-5">
    {!hideType && <fieldset>
      <legend className="text-sm font-semibold text-neutral-900 dark:text-white">
        Listing type
      </legend>
      <div className="mt-3 space-y-1.5">
        {[
          { value: 'all', label: 'All types' },
          ...MARKETPLACE_CATEGORY_DEFINITIONS.map((item) => ({
            value: item.key,
            label: item.label,
          })),
        ].map((option) => (
          <label
            key={option.value}
            className="flex min-h-11 cursor-pointer items-center gap-3 rounded-xl px-2 text-sm text-neutral-700 hover:bg-black/[0.035] dark:text-white/65 dark:hover:bg-white/[0.04]"
          >
            <input
              type="radio"
              name="marketplace-type"
              value={option.value}
              checked={filters.type === option.value}
              onChange={() =>
                onChange('type', option.value as MarketplaceFilters['type'])
              }
              className="h-4 w-4 accent-indigo-600"
            />
            {option.label}
          </label>
        ))}
      </div>
    </fieldset>}

    {categories.length > 0 && (
      <label className="block">
        <span className="mb-2 block text-sm font-semibold text-neutral-900 dark:text-white">
          Category
        </span>
        <select
          value={filters.category}
          onChange={(event) => onChange('category', event.target.value)}
          className={inputClass}
        >
          <option value="">All categories</option>
          {categories.map((category) => (
            <option key={category} value={category}>
              {category}
            </option>
          ))}
        </select>
      </label>
    )}

    <fieldset>
      <legend className="text-sm font-semibold text-neutral-900 dark:text-white">
        Price
      </legend>
      <div className="mt-3 grid grid-cols-3 gap-2">
        {(['all', 'free', 'paid'] as const).map((value) => (
          <button
            key={value}
            type="button"
            onClick={() => onChange('price', value)}
            className={`min-h-11 rounded-xl border px-2 text-sm font-medium capitalize ${
              filters.price === value
                ? 'border-indigo-500 bg-indigo-500 text-white'
                : 'border-black/10 text-neutral-700 hover:bg-black/[0.035] dark:border-white/10 dark:text-white/65 dark:hover:bg-white/[0.04]'
            }`}
          >
            {value}
          </button>
        ))}
      </div>
      <div className="mt-3 grid grid-cols-2 gap-2">
        <label>
          <span className="sr-only">Minimum price</span>
          <input
            type="number"
            min="0"
            inputMode="decimal"
            placeholder="Min"
            value={filters.minimumPrice ?? ''}
            onChange={(event) =>
              onChange('minimumPrice', optionalNumber(event.target.value))
            }
            className={inputClass}
          />
        </label>
        <label>
          <span className="sr-only">Maximum price</span>
          <input
            type="number"
            min="0"
            inputMode="decimal"
            placeholder="Max"
            value={filters.maximumPrice ?? ''}
            onChange={(event) =>
              onChange('maximumPrice', optionalNumber(event.target.value))
            }
            className={inputClass}
          />
        </label>
      </div>
    </fieldset>

    {hasBilling && <label className="block">
      <span className="mb-2 block text-sm font-semibold text-neutral-900 dark:text-white">
        Billing
      </span>
      <select
        value={filters.billing}
        onChange={(event) =>
          onChange('billing', validBilling(event.target.value))
        }
        className={inputClass}
      >
        <option value="all">Any billing type</option>
        <option value="one-time">One-time</option>
        <option value="recurring">Recurring</option>
      </select>
    </label>}

    {hasRatings && (
      <label className="block">
        <span className="mb-2 block text-sm font-semibold text-neutral-900 dark:text-white">
          Minimum rating
        </span>
        <select
          value={filters.minimumRating ?? ''}
          onChange={(event) =>
            onChange('minimumRating', optionalNumber(event.target.value))
          }
          className={inputClass}
        >
          <option value="">Any rating</option>
          <option value="4">4.0 and above</option>
          <option value="3">3.0 and above</option>
        </select>
      </label>
    )}
  </div>
);

export const MarketplaceBrowsePage = ({
  title,
  description,
  canonicalPath,
  fixedType,
  noIndex = false,
  eyebrow = 'Wersee Marketplace',
}: MarketplaceBrowsePageProps) => {
  const [searchParams, setSearchParams] = useSearchParams();
  const [queryInput, setQueryInput] = useState(searchParams.get('q') || '');
  const [listings, setListings] = useState<MarketplaceListing[]>([]);
  const [truncated, setTruncated] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [attempt, setAttempt] = useState(0);
  const [filtersOpen, setFiltersOpen] = useState(false);
  const filterButtonRef = useRef<HTMLButtonElement>(null);
  const filterDialogRef = useRef<HTMLDivElement>(null);

  const filters = useMemo<MarketplaceFilters>(
    () => ({
      query: searchParams.get('q') || '',
      type: fixedType || validType(searchParams.get('type')),
      category: searchParams.get('category') || '',
      price: validPrice(searchParams.get('price')),
      billing: validBilling(searchParams.get('billing')),
      minimumPrice: optionalNumber(searchParams.get('min')),
      maximumPrice: optionalNumber(searchParams.get('max')),
      minimumRating: optionalNumber(searchParams.get('rating')),
      sort: validSort(searchParams.get('sort')),
    }),
    [fixedType, searchParams],
  );

  useEffect(() => {
    setQueryInput(searchParams.get('q') || '');
  }, [searchParams]);

  useEffect(() => {
    const timer = window.setTimeout(() => {
      if (queryInput.trim() === filters.query) return;
      const next = new URLSearchParams(searchParams);
      if (queryInput.trim()) next.set('q', queryInput.trim());
      else next.delete('q');
      setSearchParams(next, { replace: true });
    }, 300);
    return () => window.clearTimeout(timer);
  }, [filters.query, queryInput, searchParams, setSearchParams]);

  useEffect(() => {
    let active = true;
    setLoading(true);
    setError('');
    void fetchMarketplaceListings({ limit: 200, filters })
      .then((result) => {
        if (active) {
          setListings(result.listings);
          setTruncated(result.truncated);
        }
      })
      .catch(() => {
        if (active) {
          setListings([]);
          setTruncated(false);
          setError('Published listings could not be retrieved.');
        }
      })
      .finally(() => {
        if (active) setLoading(false);
      });
    return () => {
      active = false;
    };
  }, [attempt, filters]);

  useEffect(() => {
    if (!filtersOpen) return;
    const dialog = filterDialogRef.current;
    const focusable = () =>
      Array.from(
        dialog?.querySelectorAll<HTMLElement>(
          'button:not([disabled]), input:not([disabled]), select:not([disabled]), a[href]',
        ) || [],
      );
    const first = focusable()[0];
    first?.focus();
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        setFiltersOpen(false);
        return;
      }
      if (event.key !== 'Tab') return;
      const elements = focusable();
      if (!elements.length) return;
      const firstElement = elements[0];
      const lastElement = elements[elements.length - 1];
      if (event.shiftKey && document.activeElement === firstElement) {
        event.preventDefault();
        lastElement.focus();
      } else if (!event.shiftKey && document.activeElement === lastElement) {
        event.preventDefault();
        firstElement.focus();
      }
    };
    document.addEventListener('keydown', handleKeyDown);
    document.body.style.overflow = 'hidden';
    return () => {
      document.removeEventListener('keydown', handleKeyDown);
      document.body.style.overflow = '';
      filterButtonRef.current?.focus();
    };
  }, [filtersOpen]);

  const updateFilter = <Key extends keyof MarketplaceFilters>(
    key: Key,
    value: MarketplaceFilters[Key],
  ) => {
    const next = new URLSearchParams(searchParams);
    const paramNames: Record<keyof MarketplaceFilters, string> = {
      query: 'q',
      type: 'type',
      category: 'category',
      price: 'price',
      billing: 'billing',
      minimumPrice: 'min',
      maximumPrice: 'max',
      minimumRating: 'rating',
      sort: 'sort',
    };
    const defaults: Partial<MarketplaceFilters> = {
      query: '',
      type: 'all',
      category: '',
      price: 'all',
      billing: 'all',
      minimumPrice: null,
      maximumPrice: null,
      minimumRating: null,
      sort: 'relevance',
    };
    if (value === defaults[key] || value === '' || value === null) {
      next.delete(paramNames[key]);
    } else {
      next.set(paramNames[key], String(value));
    }
    setSearchParams(next, { replace: true });
    if (key === 'sort') {
      trackMarketplaceEvent('marketplace_sort_changed', { sort: String(value) });
    } else if (key !== 'query') {
      trackMarketplaceEvent('marketplace_filter_applied', {
        filter: key,
        value: String(value),
      });
    }
  };

  const clearAll = () => {
    const next = new URLSearchParams();
    if (fixedType) next.set('type', fixedType);
    setQueryInput('');
    setSearchParams(next, { replace: true });
  };

  const submitSearch = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const next = new URLSearchParams(searchParams);
    if (queryInput.trim()) next.set('q', queryInput.trim());
    else next.delete('q');
    setSearchParams(next);
    trackMarketplaceEvent('marketplace_search_submitted', {
      surface: fixedType || 'search',
      has_query: Boolean(queryInput.trim()),
    });
  };

  const categories = useMemo(
    () =>
      [...new Set(listings.map((listing) => listing.category).filter(Boolean))]
        .filter((value): value is string => Boolean(value))
        .sort((a, b) => a.localeCompare(b)),
    [listings],
  );
  const hasRatings = listings.some((listing) => listing.ratingCount > 0);
  const hasBilling =
    filters.billing !== 'all' ||
    listings.some((listing) => Boolean(listing.billingInterval));
  const activeFilters = [
    filters.type !== 'all' && !fixedType
      ? {
          key: 'type',
          label:
            MARKETPLACE_CATEGORY_DEFINITIONS.find(
              (item) => item.key === filters.type,
            )?.label || filters.type,
        }
      : null,
    filters.category
      ? { key: 'category', label: filters.category }
      : null,
    filters.price !== 'all'
      ? { key: 'price', label: filters.price === 'free' ? 'Free' : 'Paid' }
      : null,
    filters.billing !== 'all'
      ? { key: 'billing', label: filters.billing }
      : null,
    filters.minimumPrice !== null
      ? { key: 'minimumPrice', label: `Min ${filters.minimumPrice}` }
      : null,
    filters.maximumPrice !== null
      ? { key: 'maximumPrice', label: `Max ${filters.maximumPrice}` }
      : null,
    filters.minimumRating !== null
      ? { key: 'minimumRating', label: `${filters.minimumRating}+ rating` }
      : null,
  ].filter(
    (
      item,
    ): item is {
      key: keyof MarketplaceFilters;
      label: string;
    } => Boolean(item),
  );

  const canonicalQuery =
    noIndex && filters.query
      ? `${canonicalPath}?q=${encodeURIComponent(filters.query)}`
      : canonicalPath;
  const breadcrumbJsonLd = fixedType
    ? {
        '@context': 'https://schema.org',
        '@type': 'BreadcrumbList',
        itemListElement: [
          {
            '@type': 'ListItem',
            position: 1,
            name: 'Marketplace',
            item: 'https://www.wersee.com/',
          },
          {
            '@type': 'ListItem',
            position: 2,
            name: title,
            item: `https://www.wersee.com${canonicalPath}`,
          },
        ],
      }
    : undefined;

  return (
    <div className="min-h-screen bg-[#f6f6f7] text-neutral-950 dark:bg-[#070707] dark:text-white">
      <SEO
        title={title}
        description={description}
        url={canonicalQuery}
        noIndex={noIndex}
        jsonLd={breadcrumbJsonLd}
      />
      <main className="mx-auto max-w-[1440px] px-4 pb-20 pt-28 sm:px-6 sm:pt-32 lg:px-8">
        {fixedType && (
          <nav aria-label="Breadcrumb" className="mb-6">
            <ol className="flex items-center gap-1.5 text-sm text-neutral-500 dark:text-white/45">
              <li>
                <Link to="/" className="hover:text-indigo-600 dark:hover:text-white">
                  Marketplace
                </Link>
              </li>
              <li aria-hidden="true">
                <ChevronRight className="h-4 w-4" />
              </li>
              <li aria-current="page" className="text-neutral-800 dark:text-white/75">
                {title}
              </li>
            </ol>
          </nav>
        )}

        <section className="max-w-4xl">
          <p className="text-sm font-semibold text-indigo-600 dark:text-indigo-300">
            {eyebrow}
          </p>
          <h1 className="mt-3 text-[clamp(2.35rem,5vw,4.6rem)] font-semibold leading-[1.02] tracking-[-0.05em]">
            {title}
          </h1>
          <p className="mt-4 max-w-3xl text-base leading-7 text-neutral-600 dark:text-white/55">
            {description}
          </p>
        </section>

        <form
          onSubmit={submitSearch}
          role="search"
          className="mt-8 flex max-w-4xl gap-2"
        >
          <label htmlFor="marketplace-results-search" className="sr-only">
            Search published marketplace listings
          </label>
          <div className="relative min-w-0 flex-1">
            <Search className="pointer-events-none absolute left-4 top-1/2 h-5 w-5 -translate-y-1/2 text-neutral-400 dark:text-white/35" />
            <input
              id="marketplace-results-search"
              type="search"
              value={queryInput}
              onChange={(event) => setQueryInput(event.target.value)}
              placeholder={
                fixedType
                  ? `Search within ${title.toLowerCase()}…`
                  : 'Search listings, categories and creators…'
              }
              className="h-14 w-full rounded-2xl border border-black/10 bg-white pl-12 pr-4 text-base outline-none placeholder:text-neutral-400 focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/10 dark:border-white/12 dark:bg-[#111] dark:text-white dark:placeholder:text-white/30"
            />
          </div>
          <button
            type="submit"
            className="hidden h-14 rounded-2xl bg-indigo-600 px-6 text-sm font-semibold text-white hover:bg-indigo-500 sm:inline-flex sm:items-center"
          >
            Search
          </button>
        </form>

        <div className="mt-8 flex flex-wrap items-center justify-between gap-3 border-y border-black/[0.07] py-4 dark:border-white/[0.08]">
          <p className="text-sm text-neutral-600 dark:text-white/55" aria-live="polite">
            {loading
              ? 'Loading published listings…'
              : `${listings.length}${truncated ? '+' : ''} ${listings.length === 1 ? 'result' : 'results'}`}
          </p>
          <div className="flex items-center gap-2">
            <button
              ref={filterButtonRef}
              type="button"
              onClick={() => setFiltersOpen(true)}
              className="inline-flex min-h-11 items-center gap-2 rounded-xl border border-black/10 bg-white px-4 text-sm font-semibold lg:hidden dark:border-white/10 dark:bg-white/[0.04]"
            >
              <SlidersHorizontal className="h-4 w-4" />
              Filters
              {activeFilters.length > 0 && (
                <span className="rounded-full bg-indigo-600 px-2 py-0.5 text-xs text-white">
                  {activeFilters.length}
                </span>
              )}
            </button>
            <label className="flex items-center gap-2">
              <span className="hidden text-sm text-neutral-500 dark:text-white/45 sm:inline">
                Sort
              </span>
              <select
                value={filters.sort}
                onChange={(event) =>
                  updateFilter('sort', validSort(event.target.value))
                }
                className="h-11 rounded-xl border border-black/10 bg-white px-3 text-sm font-medium outline-none focus:border-indigo-500 dark:border-white/10 dark:bg-[#111] dark:text-white"
              >
                <option value="relevance">Relevance</option>
                <option value="newest">Newest</option>
                <option value="price-asc">Price: low to high</option>
                <option value="price-desc">Price: high to low</option>
                {hasRatings && <option value="rating">Top rated</option>}
              </select>
            </label>
          </div>
        </div>

        {activeFilters.length > 0 && (
          <div className="mt-4 flex flex-wrap items-center gap-2" aria-label="Active filters">
            {activeFilters.map((filter) => (
              <button
                key={filter.key}
                type="button"
                onClick={() =>
                  updateFilter(
                    filter.key,
                    filter.key === 'type'
                      ? 'all'
                      : filter.key === 'price' || filter.key === 'billing'
                        ? 'all'
                        : filter.key === 'minimumPrice' ||
                            filter.key === 'maximumPrice' ||
                            filter.key === 'minimumRating'
                          ? null
                          : '',
                  )
                }
                className="inline-flex min-h-10 items-center gap-1.5 rounded-full border border-indigo-500/25 bg-indigo-500/[0.07] px-3 text-xs font-semibold text-indigo-700 hover:bg-indigo-500/12 dark:text-indigo-200"
              >
                {filter.label} <X className="h-3.5 w-3.5" />
              </button>
            ))}
            <button
              type="button"
              onClick={clearAll}
              className="inline-flex min-h-10 items-center px-2 text-xs font-semibold text-neutral-600 hover:text-indigo-600 dark:text-white/50 dark:hover:text-white"
            >
              Clear all
            </button>
          </div>
        )}

        <div className="mt-8 grid gap-8 lg:grid-cols-[250px_minmax(0,1fr)]">
          <aside className="hidden lg:block" aria-label="Marketplace filters">
            <div className="sticky top-24 rounded-[1.4rem] border border-black/8 bg-white p-5 dark:border-white/10 dark:bg-[#101010]">
              <div className="mb-5 flex items-center gap-2">
                <Filter className="h-4 w-4 text-indigo-600 dark:text-indigo-300" />
                <h2 className="text-base font-semibold">Filters</h2>
              </div>
              <Filters
                filters={filters}
                categories={categories}
                hasRatings={hasRatings}
                hasBilling={hasBilling}
                hideType={Boolean(fixedType)}
                onChange={updateFilter}
              />
            </div>
          </aside>

          <section aria-label="Marketplace results">
            {loading ? (
              <MarketplaceGridSkeleton />
            ) : error ? (
              <MarketplaceErrorState
                message={error}
                onRetry={() => setAttempt((value) => value + 1)}
              />
            ) : listings.length ? (
              <MarketplaceListingGrid listings={listings} />
            ) : (
              <MarketplaceEmptyState
                title="No matching published listings"
                description="Try a broader search or remove one of the active filters."
                clearAction={clearAll}
              />
            )}
          </section>
        </div>
      </main>

      {filtersOpen && (
        <div className="fixed inset-0 z-[150] lg:hidden">
          <button
            type="button"
            aria-label="Close filters"
            onClick={() => setFiltersOpen(false)}
            className="absolute inset-0 h-full w-full bg-black/65 backdrop-blur-sm"
          />
          <div
            ref={filterDialogRef}
            role="dialog"
            aria-modal="true"
            aria-labelledby="mobile-filter-title"
            className="absolute inset-x-0 bottom-0 max-h-[88dvh] overflow-y-auto rounded-t-[1.75rem] bg-white p-5 pb-[calc(1.25rem+env(safe-area-inset-bottom))] text-neutral-950 shadow-2xl dark:bg-[#111] dark:text-white"
          >
            <div className="sticky top-0 z-10 flex items-center justify-between bg-white pb-4 dark:bg-[#111]">
              <h2 id="mobile-filter-title" className="text-xl font-semibold">
                Filters
              </h2>
              <button
                type="button"
                onClick={() => setFiltersOpen(false)}
                className="flex h-11 w-11 items-center justify-center rounded-xl border border-black/10 dark:border-white/10"
                aria-label="Close filter sheet"
              >
                <X className="h-5 w-5" />
              </button>
            </div>
            <Filters
              filters={filters}
              categories={categories}
              hasRatings={hasRatings}
              hasBilling={hasBilling}
              hideType={Boolean(fixedType)}
              onChange={updateFilter}
            />
            <div className="sticky bottom-0 mt-6 grid grid-cols-2 gap-2 bg-white pt-4 dark:bg-[#111]">
              <button
                type="button"
                onClick={clearAll}
                className="min-h-12 rounded-xl border border-black/10 text-sm font-semibold dark:border-white/10"
              >
                Clear all
              </button>
              <button
                type="button"
                onClick={() => setFiltersOpen(false)}
                className="min-h-12 rounded-xl bg-indigo-600 text-sm font-semibold text-white"
              >
                Show {listings.length} results
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};
